<?php
$id=(int)($_GET['id']??0);$edit=can_action('import_recon');echo '<div class="page-head"><div><h1>Reconciliation Review</h1><p>Every source row is retained. This compares external counts with total physical stock; it never changes inventory automatically.</p></div><a class="btn ghost" href="?page=reconciliation">Back to Reconciliation</a></div>';
if(!$id){$offset=max(0,(int)($_GET['offset']??0));$total=(int)db()->query('SELECT COUNT(*) FROM process_reconciliations')->fetchColumn();echo '<div class="card table-wrap"><table class="table"><tr><th>File / Date</th><th>Processed By</th><th>Status</th><th>View</th></tr>';foreach(db()->query('SELECT r.*,u.name FROM process_reconciliations r LEFT JOIN users u ON u.id=r.created_by ORDER BY r.id DESC LIMIT 50 OFFSET '.$offset) as $b)echo '<tr><td>'.e($b['filename']).'<br>'.e($b['created_at']).'</td><td>'.e($b['name']).'</td><td>'.e($b['status']).'</td><td><a class="btn ghost" href="?page=recon_review&id='.$b['id'].'">View</a></td></tr>';echo '</table><div class="modal-actions"><span>'.($total?($offset+1).'–'.min($total,$offset+50).' of '.$total:'No uploaded reviews').'</span>';echo rs8_pagination($total,$offset,50,array_replace($_GET,['page'=>'recon_review']));echo '</div></div>';return;}
$b=recon_review_batch($id);$a=recon_analysis($b);$final=($_GET['step']??'')==='confirm'&&!$a['errors'];$edit=$edit&&$b['status']==='Review';echo '<div class="alert '.($a['errors']?'danger':'info').'"><b>'.e($b['filename']).' — '.e($b['status']==='Review'?($a['errors']?'Needs Correction':'Ready for Final Confirmation'):$b['status']).'</b><p>'.e(implode(' · ',$a['errors'])).'</p></div><div class="card table-wrap"><h3>'.($final?'Final Comparison Summary':'Uploaded Items & Corrections').'</h3><table class="table"><tr><th>Source Row / Item</th><th>Matched Product / SKU</th><th>External Qty</th><th>Sellable</th><th>Non-Sellable</th><th>Total Physical</th><th>Variance</th><th>Review</th></tr>';
foreach($a['rows'] as $r){echo '<tr><td>'.(int)$r['row'].' / '.e($r['item']).'</td><td>'.e($r['name']??'Unmatched').'<br>'.e($r['sku']??'').'</td><td>'.e($r['qty']).'</td><td>'.e($r['sellable']??'—').'</td><td>'.e($r['damaged']??'—').'</td><td>'.e($r['physical']??'—').'</td><td>'.e($r['variance']??'—').'</td><td>'.e($r['error']?:'Matched').'<br>'.e($r['remarks']);if($edit&&!$final)echo '<details><summary>Edit / Correct</summary><form method="post" action="actions.php" class="stack"><input type="hidden" name="action" value="recon_correct"><input type="hidden" name="batch_id" value="'.$id.'"><input type="hidden" name="row_no" value="'.$r['row'].'"><input type="hidden" name="revision" value="'.$b['revision'].'"><input type="hidden" name="return" value="recon_review&id='.$id.'">'.picker('product_id','Select correct product...',true,$r['product_id'],false).'<label>External Quantity<input name="qty" value="'.e($r['qty']).'" required></label><label>Remarks<textarea name="remarks">'.e($r['remarks']).'</textarea></label><button class="btn secondary">Save & Validate</button></form></details>';echo '</td></tr>';}echo '</table></div>';
if($edit){echo '<div class="card modal-actions">';if($final)echo '<a class="btn ghost" href="?page=recon_review&id='.$id.'">Back to Review</a><form method="post" action="actions.php" data-confirm="Save this reconciliation comparison? Inventory will not change."><input type="hidden" name="action" value="recon_confirm"><input type="hidden" name="batch_id" value="'.$id.'"><input type="hidden" name="digest" value="'.$a['digest'].'"><input type="hidden" name="return" value="recon_review&id='.$id.'"><label><input type="checkbox" name="review_ack" value="1" required> I reviewed every source row and the latest physical stock.</label><button class="btn primary">Confirm Comparison</button></form>';elseif(!$a['errors'])echo '<a class="btn primary" href="?page=recon_review&id='.$id.'&step=confirm">Submit for Final Confirmation</a>';echo '<form method="post" action="actions.php" data-confirm="Cancel this pending comparison?"><input type="hidden" name="action" value="recon_cancel"><input type="hidden" name="batch_id" value="'.$id.'"><input type="hidden" name="return" value="recon_review&id='.$id.'"><button class="btn ghost">Cancel Upload</button></form></div>';}
